  UPDATE reference_nakshatra_matrix t SET classical_source = $c$Muhurta-Cintamani, Vivaha-prakarana (Prakarana 6), Sloka 34 as printed — muhurta_chintamani:PG97:C1 (Mahidhara bhasha tika, Khemraj ed.)$c$
    WHERE t.id IN (select id from reference_nakshatra_matrix where matrix_type='nadi_kuta' and from_key=to_key) AND t.classical_source = $c$bphs:ch73$c$;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 3 THEN RAISE EXCEPTION 'curation expected 3 reference_nakshatra_matrix rows, updated %', n; END IF;
  UPDATE reference_nakshatra_matrix t SET classical_source = $c$Muhurta-Cintamani, Vivaha-prakarana (Prakarana 6), Sloka 21, 34 as printed — muhurta_chintamani:PG93:C1, muhurta_chintamani:PG97:C1 (Mahidhara bhasha tika, Khemraj ed.)$c$
    WHERE t.id IN (select id from reference_nakshatra_matrix where matrix_type='nadi_kuta' and from_key<>to_key) AND t.classical_source = $c$bphs:ch73$c$;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 6 THEN RAISE EXCEPTION 'curation expected 6 reference_nakshatra_matrix rows, updated %', n; END IF;
  UPDATE reference_nakshatra_matrix t SET classical_source = $c$Muhurta-Cintamani, Vivaha-prakarana (Prakarana 6), Sloka 25-26 as printed — muhurta_chintamani:PG94:C1 (Mahidhara bhasha tika, Khemraj ed.)$c$
    WHERE t.id IN (select id from reference_nakshatra_matrix where matrix_type='yoni_kuta' and relation_value='same_yoni') AND t.classical_source = $c$bphs:ch73$c$;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 14 THEN RAISE EXCEPTION 'curation expected 14 reference_nakshatra_matrix rows, updated %', n; END IF;
  UPDATE reference_nakshatra_matrix t SET classical_source = $c$Muhurta-Cintamani, Vivaha-prakarana (Prakarana 6), Sloka 25-26 as printed — muhurta_chintamani:PG94:C1 (Mahidhara bhasha tika, Khemraj ed.)$c$
    WHERE t.id IN (select id from reference_nakshatra_matrix where matrix_type='yoni_kuta' and relation_value='enemy') AND t.classical_source = $c$bphs:ch73$c$;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 14 THEN RAISE EXCEPTION 'curation expected 14 reference_nakshatra_matrix rows, updated %', n; END IF;
  UPDATE reference_nakshatra_matrix t SET classical_source = $c$Muhurta-Cintamani, Vivaha-prakarana (Prakarana 6), Sloka 24 (tika mark; verse-line OCR reads 27) as printed — muhurta_chintamani:PG93:C1 (Mahidhara bhasha tika, Khemraj ed.)$c$
    WHERE t.id IN (select id from reference_nakshatra_matrix where matrix_type='tara_kuta' and substring(notes from 'pos=([0-9]+)')::int in (3,5,7)) AND t.classical_source = $c$bphs:ch73$c$;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 243 THEN RAISE EXCEPTION 'curation expected 243 reference_nakshatra_matrix rows, updated %', n; END IF;
  UPDATE reference_nakshatra_matrix t SET classical_source = $c$Muhurta-Cintamani, Vivaha-prakarana (Prakarana 6), Sloka 22 as printed — muhurta_chintamani:PG93:C1 (Mahidhara bhasha tika, Khemraj ed.)$c$
    WHERE t.id IN (select id from reference_nakshatra_matrix where matrix_type='varna_kuta' and from_key in ('Brahmin','Kshatriya','Vaishya','Shudra') and to_key in ('Brahmin','Kshatriya','Vaishya','Shudra')) AND t.classical_source = $c$bphs:ch73$c$;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 16 THEN RAISE EXCEPTION 'curation expected 16 reference_nakshatra_matrix rows, updated %', n; END IF;
  UPDATE reference_nakshatra_matrix t SET classical_source = $c$Muhurta-Cintamani, Vivaha-prakarana (Prakarana 6), Sloka 27-28 as printed — muhurta_chintamani:PG94:C1, muhurta_chintamani:PG94:C2 (Mahidhara bhasha tika, Khemraj ed.)$c$
    WHERE t.id IN (select id from reference_nakshatra_matrix where matrix_type='graha_maitri_kuta' and from_key<>to_key and relation_value='friend_friend') AND t.classical_source = $c$bphs:ch73$c$;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 12 THEN RAISE EXCEPTION 'curation expected 12 reference_nakshatra_matrix rows, updated %', n; END IF;
  UPDATE reference_nakshatra_matrix t SET classical_source = $c$Muhurta-Cintamani, Vivaha-prakarana (Prakarana 6), Sloka 27-28 as printed — muhurta_chintamani:PG94:C1, muhurta_chintamani:PG94:C2 (Mahidhara bhasha tika, Khemraj ed.)$c$
    WHERE t.id IN (select id from reference_nakshatra_matrix where matrix_type='graha_maitri_kuta' and from_key<>to_key and relation_value in ('friend_neutral','neutral_friend')) AND t.classical_source = $c$bphs:ch73$c$;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 8 THEN RAISE EXCEPTION 'curation expected 8 reference_nakshatra_matrix rows, updated %', n; END IF;
  UPDATE reference_nakshatra_matrix t SET classical_source = $c$Muhurta-Cintamani, Vivaha-prakarana (Prakarana 6), Sloka 27-28 as printed — muhurta_chintamani:PG94:C1, muhurta_chintamani:PG94:C2 (Mahidhara bhasha tika, Khemraj ed.)$c$
    WHERE t.id IN (select id from reference_nakshatra_matrix where matrix_type='graha_maitri_kuta' and from_key<>to_key and relation_value='neutral_neutral') AND t.classical_source = $c$bphs:ch73$c$;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 4 THEN RAISE EXCEPTION 'curation expected 4 reference_nakshatra_matrix rows, updated %', n; END IF;
  UPDATE reference_nakshatra_matrix t SET classical_source = $c$Muhurta-Cintamani, Vivaha-prakarana (Prakarana 6), Sloka 27-28 as printed — muhurta_chintamani:PG94:C2 (Mahidhara bhasha tika, Khemraj ed.)$c$
    WHERE t.id IN (select id from reference_nakshatra_matrix where matrix_type='graha_maitri_kuta' and from_key<>to_key and relation_value='enemy_enemy') AND t.classical_source = $c$bphs:ch73$c$;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 4 THEN RAISE EXCEPTION 'curation expected 4 reference_nakshatra_matrix rows, updated %', n; END IF;
  UPDATE reference_nakshatra_matrix t SET classical_source = $c$Muhurta-Cintamani, Vivaha-prakarana (Prakarana 6), Sloka 31 as printed — muhurta_chintamani:PG96:C1 (Mahidhara bhasha tika, Khemraj ed.)$c$
    WHERE t.id IN (select id from reference_nakshatra_matrix where matrix_type='bhakoot_kuta' and ((relation_value='5/7' and from_key::int%2=0) or (relation_value='7/5' and from_key::int%2=1))) AND t.classical_source = $c$bphs:ch73$c$;
  GET DIAGNOSTICS n = ROW_COUNT;
