  UPDATE reference_nakshatra_matrix t SET classical_source = $c$Muhurta-Cintamani, Vivaha-prakarana (Prakarana 6), Sloka 21, 31 as printed — muhurta_chintamani:PG93:C1, muhurta_chintamani:PG96:C1 (Mahidhara bhasha tika, Khemraj ed.)$c$
    WHERE t.id IN (select id from reference_nakshatra_matrix where matrix_type='bhakoot_kuta' and relation_value not in ('1/11','11/1','4/8','8/4','5/7','7/5')) AND t.classical_source = $c$bphs:ch73$c$;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 72 THEN RAISE EXCEPTION 'curation expected 72 reference_nakshatra_matrix rows, updated %', n; END IF;

  -- post-flight
  EXECUTE $q$SELECT md5(COALESCE(string_agg((to_jsonb(t) - ARRAY[$v$created_at$v$]::text[])::text, E'\n' ORDER BY nakshatra_id::text COLLATE "C"), '')) FROM reference_nakshatra t$q$ INTO fp_0;
  EXECUTE $q$SELECT md5(COALESCE(string_agg((to_jsonb(t) - ARRAY[$v$created_at$v$]::text[])::text, E'\n' ORDER BY nakshatra_id::text COLLATE "C"), '')) FROM reference_nakshatra_pada t$q$ INTO fp_1;
  EXECUTE $q$SELECT md5(COALESCE(string_agg((to_jsonb(t) - ARRAY[$v$created_at$v$]::text[])::text, E'\n' ORDER BY id::text COLLATE "C"), '')) FROM reference_nakshatra_matrix t$q$ INTO fp_2;
  IF fp_0 IS DISTINCT FROM '6fa93a906b8ccdcd06d7f327243ab223' THEN RAISE EXCEPTION 'curation post-flight: reference_nakshatra content fingerprint mismatch (%)', fp_0; END IF;
  IF fp_1 IS DISTINCT FROM 'b13cacb9ae130e03c5061d41b6f936fd' THEN RAISE EXCEPTION 'curation post-flight: reference_nakshatra_pada content fingerprint mismatch (%)', fp_1; END IF;
  IF fp_2 IS DISTINCT FROM '94b383d5bebeca6900475bc6a3a4b18d' THEN RAISE EXCEPTION 'curation post-flight: reference_nakshatra_matrix content fingerprint mismatch (%)', fp_2; END IF;

  -- reseal the stored integrity contract (its sha256 covers the changed tables)
  UPDATE asset_registry SET integrity_check_sql = replace(replace(replace(integrity_check_sql, 'bbbf686205c208efe0a7f6dbd192b27e63931a9b37f442d194d8d17b72ee3fde', 'bb322e6c4f72d395f4119e9a59bf3a4c13354d963a3682d15d73c3d410e43e95'), '09eeb0e2027486201274b36427a17cee7eb1c60eceb3c3bf334c53b6fbc990a9', 'a24f56a803edcbd1c375e6a9169da0a4d8992fb524ab19adf28184d356f3a556'), '143ce4a335d0cc7fac4b7bb3137c713c238e7f6b06f2477d7ecf7aa14d88d9bb', '63c18350a0b2375e0066d3886a54b1b997b7844956fc47b7d063678311d06fbc') WHERE asset_id = 'bg_nakshatra';
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 1 THEN RAISE EXCEPTION 'curation expected 1 registry row, updated %', n; END IF;
  SELECT integrity_check_sql INTO ic FROM asset_registry WHERE asset_id = 'bg_nakshatra';
  IF ic IS NOT NULL THEN
    EXECUTE ic INTO ok;
    IF ok IS NOT TRUE THEN RAISE EXCEPTION 'curation post-flight: bg_nakshatra stored integrity_check_sql reads false'; END IF;
  END IF;
END
$curation$;
